async function upstream(db:DB){const script=await db.prepare("SELECT id,content_json,content_hash FROM v7_script_artifacts WHERE program_id=? AND lifecycle_state='FROZEN' ORDER BY updated_at DESC LIMIT 1").bind(PROGRAM_ID).first<Record<string,unknown>>();const audio=await db.prepare("SELECT id,content_json,content_hash FROM v7_design_artifacts WHERE program_id=? AND stage_key='07A' AND lifecycle_state='FROZEN' ORDER BY updated_at DESC LIMIT 1").bind(PROGRAM_ID).first<Record<string,unknown>>();const visual=await db.prepare("SELECT id,content_json,content_hash FROM v7_design_artifacts WHERE program_id=? AND stage_key='07B' AND lifecycle_state='FROZEN' ORDER BY updated_at DESC LIMIT 1").bind(PROGRAM_ID).first<Record<string,unknown>>();if(!script||!audio||!visual)throw new Error("Frozen Script, 07A and 07B contracts are required");const s=JSON.parse(String(script.content_json)) as Record<string,unknown>,a=JSON.parse(String(audio.content_json)) as Record<string,unknown>,v=JSON.parse(String(visual.content_json)) as Record<string,unknown>,sections=arr(s.sections).map(rec),runtimeSeconds=Number(s.runtimeSeconds||0);if(!sections.length||!runtimeSeconds)throw new Error("Frozen script timing is invalid");const requestPlan=buildRequestPlan(sections);return{script,audio,visual,s,a,v,sections,runtimeSeconds,requestPlan,totalBatches:requestPlan.length}}
type Slot={slotId:string;sectionId:string;ordinal:number;startSeconds:number;endSeconds:number;durationSeconds:number};
function slotsFor(sections:Record<string,unknown>[]){const out:Slot[]=[];for(const s of sections){const start=Number(s.startSeconds),end=Number(s.endSeconds),count=Math.max(1,Math.ceil((end-start)/3.4)),step=(end-start)/count;for(let i=0;i<count;i++){const a=Number((start+i*step).toFixed(3)),b=i===count-1?end:Number((start+(i+1)*step).toFixed(3));out.push({slotId:`${String(s.id)}-SHOT-${String(i+1).padStart(2,"0")}`,sectionId:String(s.id),ordinal:i+1,startSeconds:a,endSeconds:b,durationSeconds:Number((b-a).toFixed(3))})}}return out}
