const boundedText={type:"string",minLength:12,maxLength:180},fillProperties={slotId:{type:"string",minLength:3,maxLength:96},sectionId:{type:"string",minLength:1,maxLength:96},narrationClause:boundedText,visualJob:boundedText,primaryFamily:{type:"string",minLength:3,maxLength:80},secondaryFamily:{type:"string",minLength:3,maxLength:80},sourceMode:{type:"string",enum:["MAKE_ORIGINAL","SOURCE_PROVIDER","HYBRID"]},entryState:boundedText,motionEvent:boundedText,exitState:boundedText,emphasis:boundedText,transitionIntent:boundedText,audioBinding:boundedText,mobileAcceptance:boundedText,factualAcceptance:boundedText,antiRepeatControl:boundedText,providerQueries:{type:"array",minItems:3,maxItems:5,items:{type:"string",minLength:12,maxLength:140}}};
