async function processJob(env:Env,db:DB,up:Awaited<ReturnType<typeof upstream>>,job:ActiveJob){let p:Record<string,unknown>;try{p=await retrieve(env,job.provider_response_id)}catch(e){await pauseRun(env,db,job.run_id,`PROVIDER_STATUS_FAILED · ${e instanceof Error?e.message:"unknown provider error"}`);return}const status=String(p.status||"unknown"),now=new Date().toISOString();await db.prepare("UPDATE v7_shot_jobs SET provider_status=?,heartbeat_at=? WHERE id=?").bind(status,now,job.id).run();if(["queued","in_progress"].includes(status))return;const usage=await recordOpenAIUsage({db,programId:PROGRAM_ID,runId:job.run_id,stageKey:STAGE,costType:"SEMANTIC_SHOT_ORCHESTRATION",payload:p,fallbackModel:MODEL});if(status!=="completed"){const reason=String(rec(p.incomplete_details).reason||rec(p.error).message||status);await db.prepare("UPDATE v7_shot_jobs SET status='FAILED',heartbeat_at=?,finalized_at=?,error=? WHERE id=?").bind(now,now,`PROVIDER_${status.toUpperCase()} · ${reason}`,job.id).run();if(usage.actualUsd>REQUEST_COST_STOP_USD){await pauseRun(env,db,job.run_id,`COST_GUARD_PAUSED · $${usage.actualUsd.toFixed(3)} failed request exceeds $${REQUEST_COST_STOP_USD.toFixed(2)}`);return}if(!reason.includes("max_output_tokens")){await pauseRun(env,db,job.run_id,`PROVIDER_${status.toUpperCase()} · ${reason}`);return}const guarded=await rows(db,"SELECT id FROM v7_shot_jobs WHERE run_id=? AND batch_index=? AND id LIKE ?",job.run_id,job.batch_index,`%-${GUARD_VERSION}%`);if(job.id.includes(`-${GUARD_VERSION}`)&&guarded.length>MAX_SAFE_RETRIES){await pauseRun(env,db,job.run_id,`COST_GUARD_PAUSED · request ${job.batch_index+1} exhausted its one safe retry`);return}const blocker=guardBlocker(await guardStats(db,job.run_id));if(blocker)await pauseRun(env,db,job.run_id,blocker);return}try{const parsed=JSON.parse(output(p)) as Record<string,unknown>,input=batchInput(up,job.batch_index),shots=validateBatch(parsed,input),content=JSON.stringify({batchIndex:job.batch_index,shots}),hash=await sha(content);await db.batch([db.prepare("INSERT INTO v7_shot_batches (id,program_id,run_id,batch_index,status,content_json,content_hash,created_at) VALUES (?,?,?,?, 'STORED',?,?,?) ON CONFLICT(id) DO NOTHING").bind(`${job.run_id}-BATCH-${job.batch_index+1}`,PROGRAM_ID,job.run_id,job.batch_index,content,hash,now),db.prepare("UPDATE v7_shot_jobs SET status='COMPLETED',provider_status='completed',heartbeat_at=?,finalized_at=?,error=null WHERE id=?").bind(now,now,job.id)]);if(usage.actualUsd>REQUEST_COST_STOP_USD){await pauseRun(env,db,job.run_id,`COST_GUARD_PAUSED · $${usage.actualUsd.toFixed(3)} request exceeds $${REQUEST_COST_STOP_USD.toFixed(2)}`);return}const blocker=guardBlocker(await guardStats(db,job.run_id));if(blocker)await pauseRun(env,db,job.run_id,blocker)}catch(e){await db.prepare("UPDATE v7_shot_jobs SET status='FAILED',heartbeat_at=?,finalized_at=?,error=? WHERE id=?").bind(now,now,e instanceof Error?e.message:"BATCH_FINALIZATION_FAILED",job.id).run();await pauseRun(env,db,job.run_id,e instanceof Error?e.message:"BATCH_FINALIZATION_FAILED")}}
async function poll(){const env=await runtime(),db=env.DB!,up=await upstream(db),run=await db.prepare("SELECT id,status FROM v7_shot_runs WHERE program_id=? AND status='RUNNING' ORDER BY started_at DESC LIMIT 1").bind(PROGRAM_ID).first<{id:string;status:string}>();if(!run)return snapshot();const limit=await adaptiveParallel(db,run.id);let active=(await rows(db,"SELECT id,run_id,batch_index,provider_response_id FROM v7_shot_jobs WHERE run_id=? AND status='ACTIVE' ORDER BY batch_index LIMIT ?",run.id,limit)) as ActiveJob[];if(!active.length)await fillCapacity(env,db,up,run.id);else await Promise.all(active.map(job=>processJob(env,db,up,job)));const current=await db.prepare("SELECT status FROM v7_shot_runs WHERE id=?").bind(run.id).first<{status:string}>();if(current?.status!=="RUNNING")return snapshot();const stored=await rows(db,"SELECT batch_index FROM v7_shot_batches WHERE run_id=?",run.id);await db.prepare("UPDATE v7_shot_runs SET completed_batches=? WHERE id=?").bind(stored.length,run.id).run();active=await rows(db,"SELECT id,run_id,batch_index,provider_response_id FROM v7_shot_jobs WHERE run_id=? AND status='ACTIVE'",run.id) as ActiveJob[];if(stored.length>=up.totalBatches&&!active.length)await finalize(env,db,up,run.id);else{const effective=await fillCapacity(env,db,up,run.id),refreshed=await rows(db,"SELECT batch_index FROM v7_shot_jobs WHERE run_id=? AND status='ACTIVE'",run.id);const stillRunning=await db.prepare("SELECT status FROM v7_shot_runs WHERE id=?").bind(run.id).first<{status:string}>();if(stillRunning?.status==="RUNNING")await db.prepare("UPDATE v7_stage_states SET evidence_summary=?,updated_at=? WHERE id=?").bind(`${stored.length}/${up.totalBatches} stored · ${refreshed.length}/${effective||limit} guarded requests active`,new Date().toISOString(),`${PROGRAM_ID}-STAGE-08`).run()}return snapshot()}
async function applyCostGuard(){const env=await runtime(),db=env.DB!,run=await db.prepare("SELECT id,total_batches FROM v7_shot_runs WHERE program_id=? AND status IN ('RUNNING','FAILED','PAUSED','REPAIR_REQUIRED') ORDER BY started_at DESC LIMIT 1").bind(PROGRAM_ID).first<{id:string;total_batches:number}>();if(!run)return snapshot();const stored=await rows(db,"SELECT batch_index FROM v7_shot_batches WHERE run_id=?",run.id);await pauseRun(env,db,run.id,`COST_GUARD_PAUSED · ${stored.length}/${Number(run.total_batches)} batches preserved; guarded resume requires available provider credit`);await db.prepare("UPDATE v7_shot_runs SET completed_batches=? WHERE id=?").bind(stored.length,run.id).run();return snapshot()}
async function emergencyStop(){const env=await runtime(),db=env.DB!,result=await stopOutstanding(env,db,"User requested emergency stop",undefined,"USER_EMERGENCY");await db.prepare("UPDATE v7_stage_spend_authorizations SET status='REVOKED_BY_EMERGENCY_STOP',updated_at=? WHERE id=? AND status='ACTIVE'").bind(new Date().toISOString(),`${PROGRAM_ID}-${STAGE}-RECOVERY-AUTH`).run();return{...(await snapshot()),stopResult:result}}
async function reclassifyCostGuardStop(){const env=await runtime(),db=env.DB!,run=await db.prepare("SELECT id,total_batches FROM v7_shot_runs WHERE program_id=? ORDER BY started_at DESC LIMIT 1").bind(PROGRAM_ID).first<{id:string;total_batches:number}>();if(!run)throw new Error("No Stage 08 run exists");const outstanding=await rows(db,"SELECT id FROM v7_shot_jobs WHERE run_id=? AND (provider_status IN ('queued','in_progress') OR status='CANCEL_PENDING')",run.id);if(outstanding.length)throw new Error("REMOTE_REQUESTS_STILL_ACTIVE");const stored=await rows(db,"SELECT batch_index FROM v7_shot_batches WHERE run_id=?",run.id),g=await guardStats(db,run.id),reason=guardBlocker(g)||`COST_GUARD_PAUSED · automatic circuit breaker preserved ${stored.length}/${Number(run.total_batches)} batches`,evidence=`AUTOMATIC_COST_GUARD · ${stored.length}/${Number(run.total_batches)} stored · zero remote requests remain`,now=new Date().toISOString();await db.batch([db.prepare("UPDATE v7_shot_runs SET status='PAUSED',completed_batches=?,gate_json=?,completed_at=? WHERE id=?").bind(stored.length,JSON.stringify([{id:"COST_GUARD",label:"Automatic Cost Guard stop",status:"PASS",evidence}]),now,run.id),db.prepare("UPDATE v7_stage_states SET status='REPAIR_REQUIRED',blocker=?,evidence_summary=?,updated_at=? WHERE id=?").bind(reason,evidence,now,`${PROGRAM_ID}-STAGE-08`)]);return snapshot()}
export async function GET(){try{return Response.json(await snapshot())}catch(e){return Response.json({error:e instanceof Error?e.message:"Stage 08 could not load"},{status:500})}}
async function executeShotOrchestrationOwnerCommand(command: ShotOrchestrationOwnerCommand) {
  try {
    const body = command.payload;
    if (body.action === "EMERGENCY_STOP") return Response.json(await emergencyStop());
    if (body.action === "AUTHORIZE_RECOVERY") return Response.json(await authorizeRecovery(body.maxSpendUsd!, body.retryBudget!));
    if (body.action === "REVOKE_AUTHORIZATION") return Response.json(await revokeAuthorization());
    if (body.action === "RECLASSIFY_COST_GUARD_STOP") return Response.json(await reclassifyCostGuardStop());
    if (body.action === "RECONCILE_FROZEN_TRUTH") return Response.json(await reconcileFrozenTruth());
    if (body.action === "NORMALIZE_AND_REAUDIT") return Response.json(await normalizeAndReaudit());
    if (body.action === "SET_MODEL") return Response.json(await setModel(body.modelId!, body.reasoningEffort!));
    if (body.action === "RUN") return Response.json(await start(), { status: 202 });
    if (body.action === "RECOVER") return Response.json(await start(true), { status: 202 });
    if (body.action === "POLL") return Response.json(await poll());
    if (body.action === "APPLY_COST_GUARD") return Response.json(await applyCostGuard());
    return shotOrchestrationOwnerFailure("STAGE08_OWNER_ACTION_FORBIDDEN", 403);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Stage 08 failed";
    return Response.json(
      { error: message },
      { status: message.includes("required") || message.includes("BLOCKED") || message.includes("STILL_ACTIVE") || message.includes("AUTHORIZATION") || message.includes("INVALID") ? 409 : 500 },
    );
  }
}

export async function POST(request: Request) {
  try {
    const authorization = await authorizeShotOrchestrationOwnerWrite(request);
    if (authorization instanceof Response) return authorization;
    const command = await readShotOrchestrationOwnerCommand(request);
    if (command instanceof Response) return command;
    const identity = await shotOrchestrationOwnerAuditIdentity(request, authorization.normalizedEmail, command);
    return await runAuditedShotOrchestrationOwnerCommand(
      authorization.db,
      identity,
      command,
      () => executeShotOrchestrationOwnerCommand(command),
    );
  } catch (error) {
    console.error("Stage 08 owner POST failed", error);
    return shotOrchestrationOwnerFailure("STAGE08_OWNER_ACTION_FAILED", 500);
  }
}
